namespace Mada.WinForms;

internal static class Program
{
    /// <summary>
    /// EN: Entry point. ApplicationConfiguration.Initialize() is generated by the .NET SDK and replaces the old
    ///     EnableVisualStyles / SetCompatibleTextRenderingDefault / high-DPI calls.
    /// AR: نقطة الدخول. ApplicationConfiguration.Initialize() تُولَّد تلقائياً من ‎.NET SDK وتستبدل الاستدعاءات القديمة
    ///     EnableVisualStyles و SetCompatibleTextRenderingDefault وإعدادات الدقة العالية.
    /// </summary>
    [STAThread]
    private static void Main()
    {
        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm());
    }
}
